// Checkout conversion module - ensures paid events are generated
const { logEvent } = require('./eventLogger');

async function processCheckout(session) {
  // Simulate checkout completion
  const paid = Math.random() > 0.5; // 50% conversion for testing
  if (paid) {
    await logEvent('paid', { sessionId: session.id, amount: session.amount });
    return { success: true, paid: true };
  }
  return { success: true, paid: false };
}

module.exports = { processCheckout };
